import{_ as a,o as e,c as o,a8 as i}from"./chunks/framework.BppdKxCY.js";const u=JSON.parse('{"title":"EP.67 数字人直播的嘴型密码","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.67-obs-digital-human-av.md","filePath":"comics/EP.67-obs-digital-human-av.md","lastUpdated":1793706365000}'),l={name:"comics/EP.67-obs-digital-human-av.md"};function s(r,t,d,n,h,c){return e(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="ep-67-数字人直播的嘴型密码" tabindex="-1">EP.67 数字人直播的嘴型密码 <a class="header-anchor" href="#ep-67-数字人直播的嘴型密码" aria-label="Permalink to &quot;EP.67 数字人直播的嘴型密码&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../93-obs-digital-human-av">93-obs-digital-human-av.md</a>（93.1 obs-websocket / 93.2 协议选型 / 93.3 口型同步 / 93.5 QoS）· 示例：<code>examples/93-01-obs-digital-human-av.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：数字人声音和嘴型对不上，观众出戏。</li><li><strong>第 2 格</strong>：码叔揭秘 TTS 音素时间轴——文本→音频→音素→口型，每步带时间戳。</li><li><strong>第 3 格</strong>：像素酱实证直播协议选型——WebRTC 超低延迟适合数字人互动。</li><li><strong>第 4 格</strong>：码叔结案——obs-websocket 控制 OBS + QoS 监控码率帧率丢包。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-口型同步的核心" tabindex="-1">第 1 格 · 口型同步的核心 <a class="header-anchor" href="#第-1-格-·-口型同步的核心" aria-label="Permalink to &quot;第 1 格 · 口型同步的核心&quot;">​</a></h3><ul><li>数字人嘴型必须与音频精确对齐；</li><li>用 setTimeout 驱动口型会漂移；</li><li>必须用 <code>audio.currentTime</code> 驱动。</li></ul><h3 id="第-2-格-·-tts-音素时间轴" tabindex="-1">第 2 格 · TTS 音素时间轴 <a class="header-anchor" href="#第-2-格-·-tts-音素时间轴" aria-label="Permalink to &quot;第 2 格 · TTS 音素时间轴&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文本 → TTS(音频+音素时间戳) → 音素→口型映射 → blendshape 驱动</span></span></code></pre></div><ul><li>TTS 必须返回每个音素的 start/end 时间；</li><li>基础口型：A E I O U F M SIL；</li><li>Three.js 用 <code>morphTargetInfluences</code> 驱动口型。</li></ul><h3 id="第-3-格-·-直播协议选型" tabindex="-1">第 3 格 · 直播协议选型 <a class="header-anchor" href="#第-3-格-·-直播协议选型" aria-label="Permalink to &quot;第 3 格 · 直播协议选型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>协议</th><th>延迟</th><th>场景</th></tr></thead><tbody><tr><td>WebRTC</td><td>&lt;500ms</td><td>数字人互动、连麦</td></tr><tr><td>RTMP</td><td>1-3s</td><td>推流</td></tr><tr><td>HTTP-FLV</td><td>1-3s</td><td>PC 海量播放</td></tr><tr><td>HLS</td><td>5-30s</td><td>移动端海量</td></tr></tbody></table><p>数字人实时互动必须用 WebRTC（TRTC/火山引擎）。</p><h3 id="第-4-格-·-obs-websocket-与-qos" tabindex="-1">第 4 格 · obs-websocket 与 QoS <a class="header-anchor" href="#第-4-格-·-obs-websocket-与-qos" aria-label="Permalink to &quot;第 4 格 · obs-websocket 与 QoS&quot;">​</a></h3><ul><li>obs-websocket v5 请求-响应协议，控制 OBS 场景/推流/静音；</li><li>QoS 指标：码率、帧率、丢包率、RTT；</li><li>弱网降级：降分辨率→降帧率→关摄像头。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../93-obs-digital-human-av#_93-7-本章避坑清单">《93.7 本章避坑清单》</a></p></blockquote><ol><li>用 setTimeout 驱动口型 → 漂移，应用 audio.currentTime；</li><li>数字人用 HLS → 延迟 5s+，应用 WebRTC；</li><li>flv.js 延迟越来越大 → 设 isLive:true，超阈值重连。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>数字人口型同步的完整链路？——<strong>文本→TTS(带时间戳)→音素→口型→blendshape 驱动</strong>。</li><li>数字人实时互动用什么直播协议？——<strong>WebRTC（TRTC/火山引擎），延迟&lt;500ms</strong>。</li><li>obs-websocket 切换场景和开关推流的请求类型？——<strong>SetCurrentProgramScene / StartStopStreaming</strong>。</li></ol>',20)])])}const m=a(l,[["render",s]]);export{u as __pageData,m as default};
